from rest_framework.decorators import api_view, action
from rest_framework.viewsets import ViewSet
from rest_framework.routers import DefaultRouter

@api_view(['GET', 'POST'])
def health(request):
    pass

class handler(ViewSet):
    def list(self, request): pass
    def retrieve(self, request, pk=None): pass
    @action(methods=['post'], detail=True, url_path='publish')
    def publish(self, request, pk=None): pass

router = DefaultRouter()
router.register('projects', handler, basename='project')
